import { fail } from './protocol.js'
// The caller resolves secretRef in its trusted secret service. Never pass this object to a model.
export class RemoteAgentClient {
  constructor(private endpoint:string,private expectedMachineId:string,private secretResolver:()=>Promise<string>,private protectedTunnel=false){const u=new URL(endpoint);if(u.username||u.password||u.search||u.hash||(!['http:','https:'].includes(u.protocol)))fail('INVALID_ENDPOINT');if(u.protocol==='http:'&&!['127.0.0.1','[::1]','localhost'].includes(u.hostname)&&!protectedTunnel)fail('TLS_REQUIRED')}
  private async request(path:string,token:string,body:any){const response=await fetch(new URL(path,this.endpoint),{method:'POST',redirect:'error',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',Accept:'application/json, text/event-stream','MCP-Protocol-Version':'2025-11-25'},body:JSON.stringify(body),signal:AbortSignal.timeout(35000)});if(!response.ok)fail((await response.json()).error?.code??'AGENT_CONNECTION_FAILED',response.status);return response.json()}
  async grant(request:any){const result=await this.request('/control/v1/grants',await this.secretResolver(),request);if(result.machineId!==this.expectedMachineId||result.agentApiMajor!==1)fail('AGENT_VERSION_UNSUPPORTED');return result}
  async desktopSession(grantToken:string,request:{mode?:'watch'|'control';fps?:number;displayId?:string;origin?:string}){return this.request('/desktop/v1/session',grantToken,request)}
  async renewDesktopSession(grantToken:string,request:{sessionId:string;origin?:string}){return this.request('/desktop/v1/session/renew',grantToken,request)}
  async closeDesktopSession(grantToken:string,request:{sessionId:string}){return this.request('/desktop/v1/session/close',grantToken,request)}
  async call(grantToken:string,name:string,args:any,operationId?:string){const result=await this.request('/mcp',grantToken,{jsonrpc:'2.0',id:1,method:'tools/call',params:{name,arguments:args,_meta:{'dsh/operationId':operationId}}});if(result.error)fail('MCP_REQUEST_FAILED');if(result.result?.isError)fail(result.result.content?.[0]?.text??'EXECUTION_FAILED');return result.result.structuredContent??JSON.parse(result.result.content[0].text)}
}
